import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"Big Idea 与洞察：AI 的能力边界","description":"","frontmatter":{},"headers":[],"relativePath":"method/big-idea.md","filePath":"method/big-idea.md","lastUpdated":1786327499000}'),i={name:"method/big-idea.md"};function l(p,a,o,r,d,h){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="big-idea-与洞察-ai-的能力边界" tabindex="-1">Big Idea 与洞察：AI 的能力边界 <a class="header-anchor" href="#big-idea-与洞察-ai-的能力边界" aria-label="Permalink to &quot;Big Idea 与洞察：AI 的能力边界&quot;">​</a></h1><p>这一篇讲的是全流程里<strong>最不该交给 AI</strong>的一段，以及在这一段里 AI 还能帮上什么忙。</p><h2 id="一个残酷的观察" tabindex="-1">一个残酷的观察 <a class="header-anchor" href="#一个残酷的观察" aria-label="Permalink to &quot;一个残酷的观察&quot;">​</a></h2><p>给同一个 brief，AI 能在三十秒内产出三十条创意。这三十条的典型分布是：</p><ul><li>二十条是卖点的换句话说（「让早餐更简单」）</li><li>八条是网络热梗的套用（结构熟悉，一看就是模板）</li><li>两条有点意思，但需要人去发现它有意思</li></ul><p>**问题不在于 AI 想不出好创意，而在于它不知道哪条是好的。**它给出的三十条，语气一样自信。</p><p>所以人的位置很清楚：<strong>AI 负责穷举，人负责判断。</strong></p><h2 id="洞察不是什么" tabindex="-1">洞察不是什么 <a class="header-anchor" href="#洞察不是什么" aria-label="Permalink to &quot;洞察不是什么&quot;">​</a></h2><p>先排除三种常见的冒牌货。</p><h3 id="冒牌货一-卖点复述" tabindex="-1">冒牌货一：卖点复述 <a class="header-anchor" href="#冒牌货一-卖点复述" aria-label="Permalink to &quot;冒牌货一：卖点复述&quot;">​</a></h3><blockquote><p>❌ 「现代人生活节奏快，需要方便的早餐。」</p></blockquote><p>这是产品说明书的第一句，不是洞察。它描述的是需求，不是心理。</p><h3 id="冒牌货二-正确的废话" tabindex="-1">冒牌货二：正确的废话 <a class="header-anchor" href="#冒牌货二-正确的废话" aria-label="Permalink to &quot;冒牌货二：正确的废话&quot;">​</a></h3><blockquote><p>❌ 「每个人都值得被认真对待。」</p></blockquote><p>放到任何品类都成立，说明它没有指向任何具体的人。前面提过的检验方法在这里同样适用：<strong>换个品类还成立的，就不是这个品类的洞察。</strong></p><h3 id="冒牌货三-品牌的自我感动" tabindex="-1">冒牌货三：品牌的自我感动 <a class="header-anchor" href="#冒牌货三-品牌的自我感动" aria-label="Permalink to &quot;冒牌货三：品牌的自我感动&quot;">​</a></h3><blockquote><p>❌ 「我们坚持用最好的原料，只为那一口初心。」</p></blockquote><p>这是品牌想说的，不是消费者想听的。洞察的主语必须是消费者。</p><h2 id="洞察长什么样" tabindex="-1">洞察长什么样 <a class="header-anchor" href="#洞察长什么样" aria-label="Permalink to &quot;洞察长什么样&quot;">​</a></h2><p>一条能用的洞察，通常有这三个特征：</p><p><strong>一、它说的是一个矛盾。</strong></p><p>人的真实心理很少是单一的。「我想省事」不是洞察，「我想省事，但我不想被人看出我在省事」才是——因为它有张力，张力能生出创意。</p><p><strong>二、说出来会让人有点不好意思。</strong></p><p>好洞察往往触及一些不太体面的真实：懒、虚荣、怕落后、想被夸。正能量的洞察通常是假的，因为人不是那样活的。</p><p><strong>三、具体到能看见画面。</strong></p><p>「年轻人压力大」看不见画面。「早上闹钟响第三遍，人还躺着，脑子里已经在算今天最晚几点出门还不算迟到」——能看见。</p><h2 id="ai-在这一步的三种正确用法" tabindex="-1">AI 在这一步的三种正确用法 <a class="header-anchor" href="#ai-在这一步的三种正确用法" aria-label="Permalink to &quot;AI 在这一步的三种正确用法&quot;">​</a></h2><h3 id="用法一-当发散器-禁止提产品" tabindex="-1">用法一：当发散器（禁止提产品） <a class="header-anchor" href="#用法一-当发散器-禁止提产品" aria-label="Permalink to &quot;用法一：当发散器（禁止提产品）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我在为 [品类] 做广告，目标人群是 [具体描述]。</span></span>
<span class="line"><span>请列出 20 条这群人在 [具体场景] 里可能有的、说不出口的真实心理。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>- 不要提到任何产品</span></span>
<span class="line"><span>- 不要正能量、不要励志</span></span>
<span class="line"><span>- 越具体越好，最好能看见画面</span></span>
<span class="line"><span>- 允许负面、矛盾、不体面的心理</span></span></code></pre></div><p>「不要提到任何产品」是这段 Prompt 的核心约束。去掉它，AI 会立刻退回卖点复述。</p><h3 id="用法二-当反方-压力测试" tabindex="-1">用法二：当反方（压力测试） <a class="header-anchor" href="#用法二-当反方-压力测试" aria-label="Permalink to &quot;用法二：当反方（压力测试）&quot;">​</a></h3><p>有了候选创意后，让 AI 站在对立面攻击它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是我的广告创意：[创意描述]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请扮演一个刻薄的甲方，列出 10 条你会否掉这个创意的理由。</span></span>
<span class="line"><span>不要客气，不要给建设性意见，只管挑刺。</span></span></code></pre></div><p>AI 当批评者比当创作者靠谱得多。因为挑刺是有明确标准的任务，而判断好坏没有。</p><h3 id="用法三-当延展器-验证第二条标准" tabindex="-1">用法三：当延展器（验证第二条标准） <a class="header-anchor" href="#用法三-当延展器-验证第二条标准" aria-label="Permalink to &quot;用法三：当延展器（验证第二条标准）&quot;">​</a></h3><p>前面说过，好的 Big Idea 要能画出至少三个不同的画面。让 AI 来验证：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Big Idea：[一句话]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请基于这个概念，写出 5 个完全不同的 30 秒广告场景。</span></span>
<span class="line"><span>场景之间不能共用同一个设定或转折方式。</span></span></code></pre></div><p>如果 AI 写到第三个就开始重复，说明这个概念的延展性不够，值得回炉。</p><h2 id="ai-在这一步的三种错误用法" tabindex="-1">AI 在这一步的三种错误用法 <a class="header-anchor" href="#ai-在这一步的三种错误用法" aria-label="Permalink to &quot;AI 在这一步的三种错误用法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误用法</th><th>会发生什么</th></tr></thead><tbody><tr><td>直接问「给我一个广告创意」</td><td>得到平均值。AI 的输出天然趋向训练数据里最常见的表达，而广告最怕平均</td></tr><tr><td>让 AI 从洞察一路做到 slogan</td><td>中间没有人的筛选，误差会逐级放大，最后产出一个自洽但没人在意的东西</td></tr><tr><td>用 AI 判断哪条创意更好</td><td>它会挑「看起来最像好创意」的那条——通常是最套路的那条</td></tr></tbody></table><h2 id="一个可操作的判断清单" tabindex="-1">一个可操作的判断清单 <a class="header-anchor" href="#一个可操作的判断清单" aria-label="Permalink to &quot;一个可操作的判断清单&quot;">​</a></h2><p>拿到候选创意后，逐条过一遍：</p><ul><li>[ ] 换成竞品还成立吗？成立就废掉。</li><li>[ ] 能一句话讲完吗？讲不完说明还没想清楚。</li><li>[ ] 讲给不懂行的朋友听，他会追问细节还是礼貌点头？点头就是没打动。</li><li>[ ] 能画出三个以上不重样的画面吗？</li><li>[ ] 里面有没有一个「但是」？（矛盾往往是创意的发动机）</li></ul><p>五条里过不了三条，别往下走。分镜和生成阶段的所有努力，都救不回一个平庸的 Big Idea——只会把它更清晰地呈现出来。</p><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li>创意定了，往下走 → <a href="/method/storyboard">分镜设计：镜头语言翻译表</a></li><li>想看完整流程 → <a href="/method/workflow-sop">从 brief 到成片：完整链路 SOP</a></li></ul>`,46)])])}const u=e(i,[["render",l]]);export{b as __pageData,u as default};
